{"implementation": "def solve(case):
    import math
    matrix = case['matrix']
    n = len(matrix)
    m = len(matrix[0]) if n > 0 else 0
    row_degree = [sum(row) for row in matrix]
    df = [0] * m
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    idf = []
    for j in range(m):
        if df[j] == 0:
            idf.append(0.0)
        else:
            idf.append(math.log(n / df[j]))
    weighted = [[matrix[i][j] * idf[j] for j in range(m)] for i in range(n)]
    return {'idf': idf, 'row_degree': row_degree, 'weighted_matrix': weighted}
